import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    grid = data[2:2 + r]
    word = data[2 + r]
    m = int(data[3 + r])
    words = data[4 + r:4 + r + m]
    s = data[4 + r + m]

    # Task 1: bitset per row, bit j = column j
    rm = []
    for row in grid:
        d = {}
        for j, ch in enumerate(row):
            d[ch] = d.get(ch, 0) | (1 << j)
        rm.append(d)
    L = len(word)
    nxt = [0] * (r + 1)
    for k in range(L - 1, -1, -1):
        cur = [0] * (r + 1)
        ch = word[k]
        for i in range(r):
            ok = rm[i].get(ch, 0)
            if k < L - 1:
                ok &= nxt[i + 1] | (nxt[i] >> 1)
            cur[i] = ok
        nxt = cur
    ans1 = (-1, -1)
    for i in range(r):
        if nxt[i]:
            x = nxt[i]
            ans1 = (i, (x & -x).bit_length() - 1)
            break
    print(ans1[0], ans1[1])

    # Task 2: exact count signature as a big integer
    W = [1 << (17 * k) for k in range(26)]
    byLen = {}
    for idx, w in enumerate(words):
        key = 0
        for ch in w:
            key += W[ord(ch) - 97]
        d = byLen.setdefault(len(w), {})
        if key not in d:
            d[key] = idx
    pre = [0]
    for ch in s:
        pre.append(pre[-1] + W[ord(ch) - 97])
    best = None
    n = len(s)
    for ln, d in byLen.items():
        if ln > n:
            continue
        for i in range(n - ln + 1):
            k = pre[i + ln] - pre[i]
            idx = d.get(k)
            if idx is not None and (best is None or idx < best):
                best = idx
    print(words[best] if best is not None else '-')

main()

